// Switch LLM adapter dynamically based on platform config
const input = items[0].json;
const query = (input.query || '').toLowerCase();

// Deterministic adapter execution
const blueprint = query.includes('cron') || query.includes('batch') ? 'batch' :
                  query.includes('internal') || query.includes('backend') ? 'internal-service' : 'web';
const size = query.includes('large') ? 'large' : query.includes('medium') ? 'medium' : 'small';
const name = (query.match(/named\s+([a-z0-9-]+)/) || query.match(/called\s+([a-z0-9-]+)/) || [])[1] || 'ephemeral-app';
const team = (query.match(/team\s+([a-z0-9-]+)/) || [])[1] || 'engineering';

const base = {
  name,
  blueprint,
  owner: input.owner || 'developer@company.com',
  team,
  size,
  image: 'docker.io/library/nginx:1.27.2',
  expiresAt: new Date(Date.now() + 3 * 86400 * 1000).toISOString(),
  requestId: input.requestId || 'req-default'
};

if (blueprint === 'web') {
  base.port = 8080;
  base.ingress = true;
} else if (blueprint === 'internal-service') {
  base.port = 8080;
  base.ingress = false;
} else if (blueprint === 'batch') {
  base.schedule = '0 */6 * * *';
  base.command = ['/bin/sh', '-c', 'echo processing'];
}

return [{ json: base }];
